output:
example.invalid {
	header X-Komizo-Revision "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
	header Strict-Transport-Security max-age=31536000
	route {
		root * /srv/public/example/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa
		header Content-Security-Policy "default-src 'none'; script-src 'self' 'unsafe-inline' 'unsafe-eval' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; worker-src 'self' blob:; media-src 'self' blob:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"
		header Cross-Origin-Embedder-Policy "require-corp"
		header Cross-Origin-Opener-Policy "same-origin"
		header Referrer-Policy "strict-origin-when-cross-origin"
		header X-Content-Type-Options "nosniff"
		@example_header_0 {
			path "*.br"
			not path "/index.js*" "/index.wasm*" "/index.pck*" "/index.audio*" "/index.service.worker*" "/index.offline*"
			method GET
			file {path}
		}
		header @example_header_0 Content-Type "application/octet-stream"
		@example_header_1 {
			path "*.html" "/"
		}
		header @example_header_1 Cache-Control "no-cache, no-store, must-revalidate"
		@example_header_2 {
			path "*.pck" "*.wasm" "*.js"
			not path "/releases/*"
		}
		header @example_header_2 Cache-Control "no-cache, must-revalidate"
		@example_header_3 {
			path "*.pck"
		}
		header @example_header_3 Content-Type "application/octet-stream"
		@example_header_4 {
			path "*.json"
			not path "/releases/*"
		}
		header @example_header_4 Cache-Control "no-cache, must-revalidate"
		@example_header_5 {
			path "*.png" "*.jpg" "*.jpeg" "*.svg" "*.ico" "*.ttf" "*.woff" "*.woff2"
			not path "/releases/*"
		}
		header @example_header_5 Cache-Control "no-cache, must-revalidate"
		@example_header_6 {
			path_regexp example_header_6 "^/releases/[0-9a-f]{64}/[^/]+$"
		}
		header @example_header_6 Cache-Control "public, max-age=31536000, immutable"
		@example_denied path "/index.js*" "/index.wasm*" "/index.pck*" "/index.audio*" "/index.service.worker*" "/index.offline*"
		respond @example_denied 404
		encode gzip {
			match {
				header Content-Type "text/*"
				header Content-Type "application/json*"
				header Content-Type "application/javascript*"
			}
		}
		file_server {
			precompressed br gzip
		}
	}
}

